widget.solution:
#include <random>
#include <vector>

std::vector<double> normals(unsigned seed, int n) {
    std::mt19937 gen(seed);
    std::normal_distribution<double> z(0.0, 1.0);
    std::vector<double> out;
    out.reserve(n);
    for (int i = 0; i < n; ++i) out.push_back(z(gen));
    return out;
}

