#include <cmath>
#include <random>

double simulated_terminal_price(double s0, double r, double sigma, double t, unsigned seed) {
    const int n = 10000;
    std::mt19937 gen(seed);
    std::normal_distribution<double> z(0.0, 1.0);
    double drift = (r - 0.5 * sigma * sigma) * t;
    double vol = sigma * std::sqrt(t);
    double sum = 0;
    for (int i = 0; i < n; ++i) sum += s0 * std::exp(drift + vol * z(gen));
    return sum / n;
}

