#include <iomanip>
#include <iostream>
#include <random>

int main() {
    unsigned seed;
    int n;
    std::cin >> seed >> n;
    std::mt19937 gen(seed);
    std::normal_distribution<double> z(0.0, 1.0);
    double sum = 0;
    for (int i = 0; i < n; ++i) sum += z(gen);
    std::cout << std::fixed << std::setprecision(4) << sum / n << '\n';
}
